
const produtos = [];
let proximoCodigo = 1;

const moeda = new Intl.NumberFormat("pt-BR", {
    style: "currency",
        currency: "BRL"
        });

        function obterNumero(id) {
            const campo = document.getElementById(id);

                if (campo.value.trim() === "") {
                        throw new Error("Preencha todos os campos antes de continuar.");
                            }

                                const numero = Number(campo.value);

                                    if (!Number.isFinite(numero)) {
                                            throw new Error("Digite um número válido.");
                                                }

                                                    return numero;
                                                    }

                                                    function mostrarMensagem(texto, tipo = "sucesso") {
                                                        const mensagem = document.getElementById("mensagem");
                                                            mensagem.textContent = texto;
                                                                mensagem.className = `mensagem ${tipo}`;
                                                                }

                                                                function validarProduto(descricao, quantidade, valor) {
                                                                    if (descricao.trim().length < 5) {
                                                                            throw new Error("A descrição precisa ter pelo menos cinco caracteres.");
                                                                                }

                                                                                    if (!Number.isInteger(quantidade) || quantidade < 1) {
                                                                                            throw new Error("A quantidade inicial deve ser um número inteiro maior que zero.");
                                                                                                }

                                                                                                    if (!Number.isFinite(valor) || valor < 0) {
                                                                                                            throw new Error("O preço deve ser maior ou igual a zero.");
                                                                                                                }
                                                                                                                }

                                                                                                                function cadastrarProduto() {
                                                                                                                    try {
                                                                                                                            const descricao = document.getElementById("descricao").value.trim();
                                                                                                                                    const quantidade = obterNumero("quantidade");
                                                                                                                                            const valor = obterNumero("valor");

                                                                                                                                                    validarProduto(descricao, quantidade, valor);

                                                                                                                                                            produtos.push({
                                                                                                                                                                        codigo: proximoCodigo++,
                                                                                                                                                                                    descricao,
                                                                                                                                                                                                quantidade,
                                                                                                                                                                                                            valor
                                                                                                                                                                                                                    });

                                                                                                                                                                                                                            listarProdutos();
                                                                                                                                                                                                                                    atualizarResumo();
                                                                                                                                                                                                                                            mostrarMensagem("✓ Produto cadastrado com sucesso!");

                                                                                                                                                                                                                                                    ["descricao", "quantidade", "valor"].forEach(id => {
                                                                                                                                                                                                                                                                document.getElementById(id).value = "";
                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                document.getElementById("descricao").focus();

                                                                                                                                                                                                                                                                                    } catch (erro) {
                                                                                                                                                                                                                                                                                            mostrarMensagem(`⚠ ${erro.message}`, "erro");
                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                function listarProdutos() {
                                                                                                                                                                                                                                                                                                    const lista = document.getElementById("listaProdutos");
                                                                                                                                                                                                                                                                                                        lista.replaceChildren();

                                                                                                                                                                                                                                                                                                            if (produtos.length === 0) {
                                                                                                                                                                                                                                                                                                                    const vazio = document.createElement("div");
                                                                                                                                                                                                                                                                                                                            vazio.className = "vazio";
                                                                                                                                                                                                                                                                                                                                    vazio.innerHTML = "<span>📦</span>Nenhum produto cadastrado ainda.<br>Use o formulário acima para adicionar o primeiro item.";
                                                                                                                                                                                                                                                                                                                                            lista.appendChild(vazio);

                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                        produtos.forEach(produto => {
                                                                                                                                                                                                                                                                                                                                                                    const card = document.createElement("article");
                                                                                                                                                                                                                                                                                                                                                                                card.className = "produto";

                                                                                                                                                                                                                                                                                                                                                                                            const icone = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                        icone.className = "produto-icone";
                                                                                                                                                                                                                                                                                                                                                                                                                    icone.textContent = "📦";
                                                                                                                                                                                                                                                                                                                                                                                                                                icone.setAttribute("aria-hidden", "true");

                                                                                                                                                                                                                                                                                                                                                                                                                                            const detalhes = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                        detalhes.className = "produto-detalhes";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const cabecalho = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cabecalho.className = "produto-cabecalho";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const nome = document.createElement("h3");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        nome.textContent = produto.descricao;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const codigo = document.createElement("span");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                codigo.className = "codigo";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            codigo.textContent = `#${produto.codigo}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const dados = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    dados.className = "produto-dados";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const estoque = document.createElement("span");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            estoque.innerHTML = `Estoque: <strong>${produto.quantidade}</strong>`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const preco = document.createElement("span");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    preco.innerHTML = `Preço: <strong>${moeda.format(produto.valor)}</strong>`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cabecalho.append(nome, codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dados.append(estoque, preco);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        detalhes.append(cabecalho, dados);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    card.append(icone, detalhes);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                lista.appendChild(card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("contadorLista").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `${produtos.length} ${produtos.length === 1 ? "item" : "itens"}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function atualizarResumo() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const totalProdutos = produtos.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const totalUnidades = produtos.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (soma, produto) => soma + produto.quantidade, 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const valorTotal = produtos.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (soma, produto) => soma + produto.quantidade * produto.valor, 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("totalProdutos").textContent = totalProdutos;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("totalUnidades").textContent = totalUnidades;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("valorEstoque").textContent = moeda.format(valorTotal);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function buscarProdutoPorCodigo(idCampo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const codigo = obterNumero(idCampo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!Number.isInteger(codigo) || codigo < 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        throw new Error("Informe um código de produto válido.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const produto = produtos.find(item => item.codigo === codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            throw new Error("Não encontramos um produto com esse código.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return produto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function atualizarValor() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const produto = buscarProdutoPorCodigo("codigoValor");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const novoValor = obterNumero("novoValor");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (novoValor < 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            throw new Error("O novo preço não pode ser negativo.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            produto.valor = novoValor;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            atualizarResumo();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem("✓ Preço atualizado com sucesso!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("codigoValor").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("novoValor").value = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (erro) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarMensagem(`⚠ ${erro.message}`, "erro");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function atualizarQuantidade() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const produto = buscarProdutoPorCodigo("codigoQuantidade");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const novaQuantidade = obterNumero("novaQuantidade");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!Number.isInteger(novaQuantidade) || novaQuantidade < 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            throw new Error("A quantidade precisa ser um número inteiro maior que zero.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            produto.quantidade += novaQuantidade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            atualizarResumo();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarMensagem("✓ Estoque atualizado com sucesso!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("codigoQuantidade").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("novaQuantidade").value = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (erro) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarMensagem(`⚠ ${erro.message}`, "erro");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarResumo();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    